/* Traduction française — domaine Processus (partie 2). */
window.PMP_FR = window.PMP_FR || {};
Object.assign(window.PMP_FR, {
'PR201': { q: 'Quel est le principal résultat de la planification de release agile ?',
  o: ['Une liste détaillée des tâches de chaque sprint de la release, avec les heures par tâche', 'Un plan de release avec un périmètre et des dates cibles fondés sur la vélocité', 'Une référence de base du contenu signée qui ne peut pas changer pendant la release', 'Un histogramme des ressources montrant l’affectation de chaque développeur par jour'],
  e: 'La planification de release produit un plan global indiquant quelles fonctionnalités sont prévues dans quelle release, à partir de la vélocité et des priorités. Il est revu à mesure que l’équipe apprend.' },
'PR202': { q: 'Que mesurent les story points ?',
  o: ['Le nombre d’heures qu’une story prendra à un développeur moyen', 'Une taille relative, combinant effort, complexité et incertitude', 'La valeur métier de la story pour le client', 'Le coût de la story dans la monnaie de l’organisation'],
  e: 'Les story points sont une mesure relative de la taille du travail : on compare les éléments entre eux plutôt qu’à un temps d’horloge.' },
'PR203': { q: 'Au planning poker, pourquoi tous les estimateurs révèlent-ils leurs cartes en même temps ?',
  o: ['Pour terminer la séance d’estimation plus vite qu’une discussion ouverte', 'Pour éviter l’ancrage sur la première estimation entendue', 'Pour que le Product Owner puisse choisir l’estimation la plus précise', 'Pour que la moyenne de toutes les cartes puisse être calculée automatiquement'],
  e: 'La révélation simultanée évite le biais d’ancrage. Les écarts d’estimation suscitent ensuite une discussion sur les hypothèses avant un nouveau vote.' },
'PR204': { q: 'Quel est l’objectif principal de l’objectif de sprint ?',
  o: ['Lister chaque élément du backlog à terminer pendant le sprint', 'Donner au sprint un objectif unique qui apporte focus et flexibilité', 'Définir les normes de qualité que chaque incrément doit respecter', 'Rendre compte aux parties prenantes de l’avancement par rapport au plan de release'],
  e: 'L’objectif de sprint est l’objectif unique du sprint. Il crée de la cohérence et permet aux développeurs d’adapter le travail tout en livrant la valeur visée.' },
'PR205': { q: 'Quelle affirmation sur un incrément Scrum est correcte ?',
  o: ['Il doit être mis en production à la fin de chaque sprint', 'Il doit être utilisable et respecter la définition de « terminé »', 'Il comprend tous les éléments commencés pendant le sprint, terminés ou non', 'Il n’est créé que lors du dernier sprint de chaque release'],
  e: 'Un incrément est une étape utilisable et terminée vers l’objectif produit. Sa mise à disposition est une décision métier ; il peut être livré à tout moment.' },
'PR206': { q: 'Qui peut annuler un sprint dans Scrum, et quand ?',
  o: ['Le Scrum Master, quand l’équipe prend du retard sur son plan de sprint', 'Le Product Owner, quand l’objectif du sprint devient obsolète', 'Les développeurs, quand ils découvrent qu’une story est trop grosse', 'Le sponsor, quand une nouvelle demande urgente d’un client arrive'],
  e: 'Seul le Product Owner a l’autorité d’annuler un sprint, et seulement si l’objectif du sprint devient obsolète.' },
'PR207': { q: 'Dans Scrum, qu’est-ce que l’objectif produit ?',
  o: ['La liste de toutes les fonctionnalités approuvées pour la release en cours', 'Un objectif à long terme pour le produit qui guide le backlog', 'Les critères de qualité que chaque incrément doit satisfaire', 'La vélocité cible sur laquelle l’équipe s’engage pour l’année'],
  e: 'L’objectif produit décrit un état futur du produit et constitue l’objectif à long terme de l’équipe Scrum. Il figure dans le carnet de produit.' },
'PR208': { q: 'Quels DEUX facteurs le Product Owner doit-il prendre en compte pour ordonner le carnet de produit ?',
  o: ['La valeur métier et le coût du retard', 'La réduction des risques et les dépendances', 'Les préférences de chaque développeur', 'L’ordre dans lequel les parties prenantes ont soumis leurs demandes', 'Le nombre de tâches de chaque élément'],
  e: 'L’ordonnancement du backlog équilibre la valeur, le coût du retard, les risques, les dépendances et l’apprentissage. L’ordre de soumission, les préférences personnelles et le nombre de tâches ne sont pas des critères.' },
'PR209': { q: 'Quel est l’objectif principal du story mapping ?',
  o: ['Relier chaque story aux cas de test qui la vérifient pendant la release', 'Visualiser le parcours utilisateur et le découper en releases apportant de la valeur', 'Attribuer les stories aux développeurs selon leurs compétences et centres d’intérêt', 'Estimer le coût total du carnet de produit pour l’analyse de rentabilisation'],
  e: 'Une story map organise les stories selon le parcours de l’utilisateur et par priorité, ce qui aide l’équipe à voir le produit dans son ensemble et à planifier des tranches de release fines et utiles.' },
'PR210': { q: 'Qu’est-ce qu’une fonctionnalité minimale commercialisable (MMF) ?',
  o: ['La fonctionnalité la moins chère que l’équipe puisse construire en un seul sprint', 'La plus petite fonctionnalité que les clients trouveront utile', 'Une fonctionnalité techniquement terminée mais pas encore testée', 'Un prototype jetable construit seulement pour tester une hypothèse technique'],
  e: 'Une MMF est la plus petite unité de fonctionnalité ayant une valeur reconnaissable pour les utilisateurs. Un MVP, à l’inverse, vise surtout l’apprentissage validé.' },
'PR211': { q: 'Selon le modèle de Kano, comment classer une fonctionnalité que les clients n’attendent pas mais qui les enchante ?',
  o: ['Fonctionnalité de base (obligatoire)', 'Fonctionnalité de performance', 'Fonctionnalité d’enchantement (attractive)', 'Fonctionnalité indifférente'],
  e: 'Les fonctionnalités d’enchantement créent de la satisfaction lorsqu’elles sont présentes mais aucune insatisfaction lorsqu’elles sont absentes. Les fonctionnalités de base causent de l’insatisfaction si elles manquent ; celles de performance augmentent la satisfaction avec la qualité.' },
'PR212': { q: 'Un élément de travail est traité activement pendant 2 jours et attend 8 jours dans des files, soit un lead time total de 10 jours. Quelle est l’efficacité du flux, en pourcentage ?',
  e: 'Efficacité du flux = temps actif / lead time total = 2 / 10 = 20 %. La plupart du temps est de l’attente : réduire les files est la plus grande source d’amélioration.' },
'PR213': { q: 'En Kanban, que mesure le débit (throughput) ?',
  o: ['Le temps qu’un élément passe du début à la fin', 'Le nombre d’éléments terminés par unité de temps', 'Le nombre d’éléments actuellement en cours', 'Le pourcentage de temps où un élément est traité activement'],
  e: 'Le débit est le nombre d’éléments terminés par période (par exemple par semaine). Le temps de cycle mesure la durée ; le WIP mesure les éléments en cours.' },
'PR214': { q: 'Quelle pratique fait partie intégrante de la méthode Kanban ?',
  o: ['Des itérations de durée fixe avec un engagement au début de chacune', 'Rendre explicites les règles du processus et limiter le travail en cours', 'Affecter un Scrum Master dédié à chaque équipe', 'Estimer chaque élément en story points avant qu’il puisse commencer'],
  e: 'Les pratiques Kanban comprennent : visualiser le travail, limiter le WIP, gérer le flux, rendre les règles explicites, mettre en place des boucles de feedback et s’améliorer de façon collaborative.' },
'PR215': { q: 'Les limites de WIP d’une équipe Kanban ne sont jamais atteintes, mais chaque membre jongle avec cinq ou six éléments et les temps de cycle sont longs. Que doit faire l’équipe ?',
  o: ["Augmenter les limites de WIP pour qu’elles correspondent mieux au volume de travail actuel", "Abaisser les limites de WIP pour qu’elles contraignent vraiment le travail", "Supprimer les limites de WIP, puisqu’elles ne servent de toute façon à rien", "Ajouter des colonnes au tableau pour montrer plus clairement le multitâche"],
  e: 'Des limites de WIP jamais atteintes ne contraignent rien. Les abaisser réduit le multitâche et, d’après la loi de Little, le temps de cycle.' },
'PR216': { q: 'Une équipe XP pratique la propriété collective du code. Qu’est-ce que cela signifie ?',
  o: ['Chaque développeur possède un module et lui seul peut le modifier', 'Tout développeur peut améliorer n’importe quelle partie du code', 'Le Product Owner possède le code et approuve chaque modification', 'La propriété du code est attribuée au développeur le plus senior'],
  e: 'La propriété collective du code permet à chacun de modifier n’importe quel code, avec l’appui des tests et du binômage. Elle réduit les goulots d’étranglement et les silos de connaissances.' },
'PR217': { q: 'Qu’est-ce que le refactoring ?',
  o: ['Ajouter de nouvelles fonctionnalités au code existant pendant un sprint', 'Améliorer la structure interne du code sans changer son comportement', 'Réécrire toute l’application dans une nouvelle technologie', 'Corriger les défauts signalés par les clients en production'],
  e: 'Le refactoring améliore la conception, la lisibilité et la maintenabilité tout en conservant le comportement externe. Les tests automatisés le rendent sûr.' },
'PR218': { q: 'Une équipe rédige ses critères d’acceptation au format « Étant donné… Quand… Alors… » et les automatise. De quelle pratique s’agit-il ?',
  o: ['Le développement piloté par le comportement (BDD)', 'La programmation en binôme avec un testeur', 'Des séances de tests exploratoires', 'La cartographie de la chaîne de valeur du processus de test'],
  e: 'Le BDD exprime le comportement attendu sous forme d’exemples « Étant donné / Quand / Alors », créant une compréhension partagée et des spécifications exécutables.' },
'PR219': { q: 'L’organisation dispose d’une définition de « terminé » standard. Une équipe Scrum veut y ajouter des critères pour son produit. Est-ce permis ?',
  o: ['Non ; la définition de « terminé » de l’organisation doit être utilisée telle quelle', 'Oui ; l’équipe peut ajouter des critères plus stricts en plus du standard de l’organisation', 'Oui ; l’équipe peut aussi retirer les critères qu’elle juge inutiles', 'Non ; seul le Product Owner peut modifier la définition de « terminé »'],
  e: 'Si l’organisation dispose d’une définition de « terminé », les équipes doivent la respecter au minimum et peuvent y ajouter des critères plus exigeants.' },
'PR220': { q: 'Quel travail compte dans la vélocité d’une équipe pour un sprint ?',
  o: ['Toutes les stories commencées pendant le sprint', 'Uniquement les stories qui respectent la définition de « terminé »', 'Les stories achevées à au moins 80 %', 'Toutes les stories du carnet de sprint au moment de la planification'],
  e: 'La vélocité ne compte que le travail terminé. Le travail partiellement réalisé n’est pas compté et retourne dans le carnet de produit.' },
'PR221': { q: '<p>Une équipe est dans un sprint de 10 jours avec 120 heures de travail prévues. Le burndown idéal est de 12 heures par jour.</p><table><tr><th>Jour</th><th>1</th><th>3</th><th>5</th><th>7</th></tr><tr><td>Heures restantes</td><td>120</td><td>112</td><td>106</td><td>101</td></tr></table><p>Qu’indique très probablement cette tendance ?</p>',
  o: ['L’équipe est en avance et peut ajouter du travail au sprint', 'L’équipe est nettement en retard sur la ligne idéale et l’objectif du sprint est menacé', 'L’équipe est exactement dans les temps, puisque le travail restant diminue', 'Le graphique ne peut pas être interprété sans connaître la vélocité de l’équipe'],
  e: 'Au jour 7, le travail restant idéal est d’environ 120 − 6×12 = 48 heures, mais il en reste 101. L’équipe doit en rechercher la cause et discuter du périmètre avec le Product Owner.' },
'PR222': { q: 'Une release compte 300 story points. L’équipe en a terminé 120 et sa vélocité est stable à 20 points par sprint. Sans changement de périmètre, combien de sprints supplémentaires faut-il ?',
  e: 'Reste = 300 − 120 = 180 points. 180 / 20 = 9 sprints.' },
'PR223': { q: 'Le backlog restant compte 200 story points. L’équipe réalise 30 points par sprint, mais les parties prenantes ajoutent environ 10 nouveaux points à chaque sprint. Si ces deux rythmes se maintiennent, combien de sprints faudra-t-il pour terminer le backlog ?',
  e: 'Avancement net = 30 − 10 = 20 points par sprint. 200 / 20 = 10 sprints. La croissance du périmètre doit être incluse dans les prévisions.' },
'PR224': { q: 'Une équipe a en moyenne 12 éléments en cours, et chaque élément met en moyenne 3 jours du début à la fin. Selon la loi de Little, quel est le débit moyen, en éléments par jour ?',
  e: 'Loi de Little : débit = travail en cours / temps de cycle = 12 / 3 = 4 éléments par jour.' },
'PR225': { q: 'Un sprint compte 10 jours ouvrés, dont 2 jours fériés. L’équipe a 6 développeurs disposant chacun de 6 heures de concentration par jour travaillé. Quelle est la capacité de l’équipe pour le sprint, en heures ?',
  e: 'Jours travaillés = 10 − 2 = 8. Capacité = 6 développeurs × 8 jours × 6 heures = 288 heures.' },
'PR226': { q: 'Une équipe agile coûte 60 000 $ par sprint et a une vélocité stable de 30 story points par sprint. Quel est le coût par story point, en dollars ?',
  e: 'Coût par point = 60 000 / 30 = 2 000 $. Cela aide à estimer le coût des éléments du backlog et des releases.' },
'PR227': { q: 'Dans un projet hybride, quels artefacts maîtrisent généralement les composantes prédictives, tandis que les composantes agiles sont gérées par un carnet de produit ?',
  o: ['La charte d’équipe et les accords de travail', 'Les références de base du contenu, de l’échéancier et des coûts', 'Les graphiques burndown et burnup', 'La définition de « terminé » et la définition de « prêt »'],
  e: 'Les composantes prédictives sont maîtrisées par des références de base approuvées et la maîtrise des modifications ; les composantes agiles utilisent un backlog priorisé et des prévisions empiriques.' },
'PR228': { q: 'L’organisation exige des passages de phase, et le logiciel est développé par des équipes agiles. Quelle est la meilleure façon de définir les critères de passage pour le travail agile ?',
  o: ['Exiger des documents de conception complets pour toutes les fonctionnalités avant le passage', 'Fonder les décisions de passage sur des incréments démontrés et des preuves de résultats', 'Supprimer les passages pour le travail agile, puisqu’ils ne s’appliquent pas à l’agile', 'Exiger que les équipes agiles passent en cascade avant chaque passage de phase'],
  e: 'Les passages de phase peuvent être adaptés au travail agile en évaluant des incréments fonctionnels, des résultats validés et des prévisions mises à jour plutôt que des documents.' },
'PR229': { q: 'Un projet hybride achète auprès de deux fournisseurs du matériel sur mesure aux spécifications fixes et du développement logiciel agile. Quelle approche contractuelle convient le mieux ?',
  o: ['Des contrats en coûts remboursables pour les deux fournisseurs afin de garder un maximum de souplesse', 'Prix fixe pour le matériel ; temps et matériel plafonné pour le logiciel', 'Un prix fixe ferme avec un périmètre entièrement détaillé pour les deux fournisseurs', 'Du temps et matériel sans aucune limite pour les deux fournisseurs, par simplicité'],
  e: 'Les types de contrats s’adaptent à l’incertitude : le prix fixe convient au matériel bien défini ; le T&M plafonné avec possibilité de sortie convient au logiciel évolutif.' },
'PR230': { q: 'Plusieurs équipes construisent des composants qui doivent fonctionner ensemble. Les problèmes d’intégration sont généralement découverts tard. Que doit mettre en place le chef de projet ?',
  o: ['Une seule grande phase d’intégration à la fin du projet, quand toutes les équipes ont terminé', 'Une intégration fréquente dans des environnements partagés, avec des jalons d’intégration communs', 'Des environnements de test séparés pour chaque équipe afin qu’elles ne se gênent pas', 'Une règle selon laquelle chaque équipe n’intègre qu’après avoir terminé tout son travail'],
  e: 'Intégrer tôt et souvent réduit le risque d’intégration. Une intégration « big bang » à la fin cache les problèmes jusqu’à ce qu’ils coûtent cher à corriger.' },
'PR231': { q: 'Une équipe agile suit les « défauts échappés ». Qu’indique cet indicateur ?',
  o: ["Les défauts trouvés et corrigés par l’équipe dans le sprint même où ils ont été créés", "Les défauts trouvés après que le travail a été jugé terminé, par exemple en production", "Les défauts enregistrés par le Product Owner lors de la planification du sprint suivant", "Les défauts que l’équipe a décidé de ne pas corriger en raison de leur faible priorité"],
  e: 'Les défauts échappés sont découverts après la livraison. Une tendance à la hausse suggère que la définition de « terminé » ou les pratiques de test doivent être améliorées.' },
'PR232': { q: 'Quel est le principal avantage d’une suite de tests de non-régression automatisés ?',
  o: ['Elle supprime tout besoin de tests manuels ou exploratoires par l’équipe', 'Elle indique rapidement que les modifications n’ont pas cassé le comportement existant', 'Elle garantit que le produit n’a aucun défaut lors de sa mise à disposition aux clients', 'Elle remplace les critères d’acceptation des user stories par des scripts automatisés'],
  e: 'Les tests de non-régression automatisés s’exécutent vite et souvent, détectent tôt les effets de bord et sécurisent le refactoring et les releases fréquentes.' },
'PR233': { q: 'Une équipe a terminé un spike limité dans le temps. Quel est le résultat attendu ?',
  o: ['Une fonctionnalité potentiellement livrable pouvant être montrée au client', 'Des connaissances qui réduisent l’incertitude, par exemple pour estimer', 'Une conception technique entièrement documentée pour tout le produit', 'Une demande de modification signée que le Product Owner peut approuver'],
  e: 'Les spikes produisent de l’apprentissage (une réponse, un prototype ou des données), pas des fonctionnalités de production. Le résultat éclaire les estimations et les décisions.' },
'PR234': { q: 'Dans l’« oignon de planification » agile, quel niveau de planification la mêlée quotidienne représente-t-elle ?',
  o: ['La planification de release', 'La planification d’itération', 'La planification quotidienne', 'La planification de portefeuille'],
  e: 'Les couches de l’oignon de planification sont la stratégie, le portefeuille, le produit, la release, l’itération et le quotidien. La mêlée quotidienne est la planification quotidienne.' },
'PR235': { q: 'Un sprint se passe mal et l’équipe ne terminera probablement pas. Une partie prenante propose de prolonger le sprint de trois jours. Que doit-il se passer ?',
  o: ['Prolonger le sprint, car terminer tout le travail prévu est le plus important', 'Garder la durée fixe, renégocier le périmètre avec le PO et en tirer les leçons', 'Prolonger ce sprint et raccourcir le suivant pour compenser', 'Annuler le sprint et le relancer avec une durée plus longue adaptée au travail'],
  e: 'Les sprints sont des durées fixes. C’est le périmètre, et non le temps, qui s’ajuste, et l’équipe analyse les causes en rétrospective.' },
'PR236': { q: 'Le sponsor demande un diagramme de Gantt détaillé pour un produit agile. Que doit fournir le chef de projet ?',
  o: ["Un diagramme de Gantt par tâche pour chaque sprint de l’année à venir", "Une feuille de route des releases avec des fourchettes de prévision", "Rien, puisque les projets agiles ne planifient pas au-delà du sprint en cours", "Une référence de base fixe de l’échéancier sur laquelle l’équipe doit s’engager"],
  e: 'Les équipes agiles planifient à plusieurs niveaux. Une feuille de route avec des fourchettes de prévision donne aux parties prenantes une vision temporelle sans fausse précision.' },
'PR237': { q: 'Quelle est la taille recommandée d’une équipe Scrum ?',
  o: ['Petite, généralement 10 personnes ou moins', 'Au moins 15 personnes pour couvrir tous les besoins', 'Exactement 7 personnes', 'Autant que le budget du projet le permet'],
  e: 'Les équipes Scrum comptent généralement 10 personnes ou moins. Les petites équipes communiquent mieux et sont plus productives ; les grands groupes doivent se répartir en plusieurs équipes.' },
'PR238': { q: 'Une organisation a des équipes par composant (équipe IHM, équipe API, équipe base de données) et chaque fonctionnalité exige des passations entre elles. Quel changement réduirait le plus les délais ?',
  o: ['Ajouter un responsable de coordination dédié entre les équipes par composant pour gérer les passations', 'Se réorganiser en équipes fonctionnalités pluridisciplinaires qui livrent de bout en bout', 'Demander à chaque équipe par composant de travailler plus vite dans son domaine technique', 'Planifier toutes les fonctionnalités un an à l’avance pour pouvoir ordonnancer les passations'],
  e: 'Les équipes fonctionnalités ont toutes les compétences pour livrer des fonctionnalités complètes, ce qui élimine les passations et les attentes entre équipes par composant.' },
'PR239': { q: 'Plusieurs équipes Scrum travaillent sur le même produit et les dépendances posent problème. Quelle pratique aide les équipes à se coordonner au quotidien ?',
  o: ['Un « Scrum of Scrums » avec des représentants de chaque équipe', 'Un rapport d’avancement hebdomadaire de chaque équipe à la direction', 'Une seule mêlée quotidienne réunissant tous les membres de toutes les équipes', 'Un comité de contrôle des modifications pour les dépendances entre équipes'],
  e: 'Un Scrum of Scrums réunit fréquemment des représentants des équipes pour coordonner les dépendances et les obstacles inter-équipes.' },
'PR240': { q: 'Quatre équipes Scrum travaillent sur un même produit. Comment organiser le carnet de produit ?',
  o: ['Chaque équipe a son propre Product Owner et un carnet de produit séparé', 'Un seul carnet de produit et un seul Product Owner pour tout le produit', 'Les équipes possèdent le backlog à tour de rôle à chaque sprint', 'Les Scrum Masters possèdent conjointement le backlog'],
  e: 'Dans Scrum (et les approches à l’échelle comme LeSS), un produit a un seul carnet de produit et un seul Product Owner, ce qui garantit un ordre de valeur unique.' },
'PR241': { q: 'Dans SAFe, quel est l’objectif principal de la planification de PI (Program Increment) ?',
  o: ['Approuver le budget annuel et les effectifs de chaque équipe agile', 'Aligner toutes les équipes sur les objectifs et dépendances de l’incrément', 'Remplacer la planification de sprint que chaque équipe tiendrait sinon', 'Évaluer la performance individuelle des développeurs du train'],
  e: 'La planification de PI est un événement en présentiel (ou virtuel) où toutes les équipes d’un Agile Release Train planifient ensemble, identifient les dépendances et s’engagent sur des objectifs.' },
'PR242': { q: 'Quel graphique montre le mieux si une release est sur la bonne voie lorsque le périmètre change ?',
  o: ['Le graphique burndown du sprint en cours', 'Le graphique burnup de release avec une ligne de périmètre', 'L’histogramme des ressources de l’équipe de développement', 'Le diagramme de Pareto des défauts trouvés jusqu’ici'],
  e: 'Un burnup de release montre séparément le travail terminé et le périmètre total : les changements de périmètre sont visibles et l’achèvement prévu peut être projeté.' },
'PR243': { q: 'Au milieu d’un sprint, la courbe du burndown remonte au lieu de descendre. Quelle en est la cause la plus probable ?',
  o: ['L’équipe a réalisé plus de travail que prévu sur la période', 'Du nouveau travail a été découvert ou ajouté au carnet de sprint', 'La vélocité de l’équipe a augmenté par rapport au sprint précédent', 'Le Product Owner a raccourci la durée du sprint'],
  e: 'Une augmentation du travail restant signifie que du travail a été ajouté ou sous-estimé. L’équipe doit l’analyser et, si besoin, discuter du périmètre avec le Product Owner.' },
'PR244': { q: 'Au moment de la release, plusieurs stories ne respectent pas la définition de « terminé », mais le Product Owner veut les déclarer terminées. Que doit faire le Scrum Master ?',
  o: ['Accepter, puisque le Product Owner décide de ce qui est livré et quand', 'Expliquer qu’un travail non terminé ne peut pas être déclaré terminé', 'Marquer les stories comme terminées et combler les lacunes à la release suivante', 'Suspendre la définition de « terminé » pour cette release seulement, puis la rétablir'],
  e: 'La transparence est un pilier de Scrum. Le travail non terminé ne fait pas partie de l’incrément ; le Product Owner ne peut décider de ce qu’il livre qu’avec une vision honnête de son état.' },
'PR245': { q: 'Un produit réglementé est développé selon une approche hybride. Comment produire efficacement les preuves qualité de chaque release ?',
  o: ['Rédiger manuellement toute la documentation qualité à la fin du projet', 'Intégrer dans le pipeline de livraison des contrôles qualité automatisés et la collecte de preuves', 'Se passer de preuves qualité pour les composantes agiles, puisqu’elles changent trop souvent', 'Demander au régulateur d’accepter une confirmation verbale du responsable qualité'],
  e: 'Des contrôles qualité automatisés dans le pipeline (tests, analyses, approbations) génèrent en continu des preuves traçables, ce qui satisfait les régulateurs sans phase documentaire tardive.' },
'PR246': { q: 'Quel est l’objectif principal du développement piloté par les tests d’acceptation (ATDD) ?',
  o: ['Tester les performances sous la charge prévue avant la release', 'Convenir des tests d’acceptation avec le client avant de coder', 'Permettre aux testeurs de travailler indépendamment des développeurs pour éviter les biais', 'Remplacer les tests unitaires automatisés par des tests manuels structurés'],
  e: 'En ATDD, le client, les développeurs et les testeurs définissent ensemble les tests d’acceptation avant la réalisation, ce qui garantit une compréhension commune de « terminé ».' },
'PR247': { q: 'La vélocité d’une équipe a été plus faible que d’habitude pendant un sprint comprenant plusieurs jours fériés. Le Product Owner demande pourquoi. Que doit expliquer l’équipe ?',
  o: ['Que l’équipe a été moins productive ce sprint et travaillera plus dur la prochaine fois', 'Que la capacité était plus faible et que les plans doivent refléter la capacité', 'Que la vélocité n’a pas d’intérêt pour la planification et doit être ignorée', 'Que les stories de ce sprint ont été mal estimées'],
  e: 'La vélocité varie avec la capacité. Les équipes ajustent leurs plans de sprint en fonction des variations de capacité connues, comme les jours fériés.' },
'PR248': { q: 'Quelles DEUX lettres des critères INVEST d’une bonne user story sont correctement définies ?',
  o: ['I = Indépendante', 'V = Valorisable (apporte de la valeur)', 'E = Expansive (coûteuse)', 'S = Spécifique', 'T = Technique'],
  e: 'INVEST : Indépendante, Négociable, Valorisable, Estimable, Small (petite), Testable.' },
'PR249': { q: 'Quelles DEUX façons de découper une grosse user story sont efficaces ?',
  o: ['Par étapes du parcours de l’utilisateur', 'Par variantes des règles métier', 'Par couche technique, comme la base de données et l’IHM', 'Par membre de l’équipe qui réalisera le travail', 'Par nombre d’heures que prendra chaque partie'],
  e: 'Un bon découpage produit des tranches verticales qui apportent encore de la valeur, comme les étapes du parcours ou les variantes de règles métier. Découper par couche ou par personne crée des stories sans valeur propre.' },
'PR250': { q: 'Associez chaque événement Scrum à son objectif principal.',
  o: ['Planification de sprint', 'Mêlée quotidienne', 'Revue de sprint', 'Rétrospective de sprint'],
  m: ['Définir l’objectif du sprint et planifier le travail du sprint', 'Inspecter la progression vers l’objectif du sprint et adapter le plan pour le jour suivant', 'Inspecter l’incrément avec les parties prenantes et adapter le carnet de produit', 'Inspecter la façon dont l’équipe a travaillé et planifier des améliorations'],
  e: 'Chaque événement Scrum est une occasion d’inspecter et d’adapter : planifier, se synchroniser, revoir le produit et améliorer le processus.' },
'PR251': { q: 'Associez chaque catégorie du modèle de Kano à sa description.',
  o: ['De base (obligatoire)', 'De performance', 'D’enchantement', 'Indifférente'],
  m: ['Provoque de l’insatisfaction si elle est absente mais peu de satisfaction si elle est présente', 'La satisfaction augmente proportionnellement à la qualité de sa réalisation', 'Inattendue ; crée une forte satisfaction mais aucune insatisfaction si elle est absente', 'Les clients ne se soucient pas de sa présence'],
  e: 'Le modèle de Kano aide à prioriser : d’abord les fonctions de base, puis celles de performance, avec quelques fonctions d’enchantement pour se différencier.' },
'PR252': { q: 'Lorsqu’on applique la valeur acquise à une release agile, qu’utilise-t-on généralement comme base de la valeur planifiée ?',
  o: ['Les heures saisies sur les feuilles de temps de l’équipe', 'Les story points prévus dans le plan de release', 'Le nombre de développeurs affectés à l’équipe', 'Le nombre de défauts trouvés à chaque sprint'],
  e: 'L’AgileEVM utilise le plan de release (points prévus par sprint et budget) comme référence de valeur planifiée et les points terminés comme valeur acquise.' },
'PR253': { q: 'Dans un projet agile, un rapport réglementaire doit être livré à une date limite légale fixe. Comment l’équipe doit-elle le gérer ?',
  o: ["Le traiter comme n’importe quel élément du backlog pouvant être dépriorisé", "Le traiter comme une contrainte fixe et le planifier à temps", "Le gérer en dehors du backlog sans en informer le Product Owner", "Attendre le dernier sprint avant l’échéance pour le commencer"],
  e: 'Les livrables obligatoires et datés sont des contraintes. Le Product Owner ordonne le backlog pour que le travail soit terminé à temps, idéalement avec une marge.' },
'PR254': { q: 'Un fournisseur externe suit une approche prédictive, tandis que l’équipe interne est agile. Comment le chef de projet doit-il coordonner leur travail ?',
  o: ['Exiger que le fournisseur adopte immédiatement Scrum pour que les deux côtés travaillent de la même façon', 'Convenir de jalons d’interface et de points d’intégration', 'Laisser chaque partie travailler indépendamment jusqu’à la fin du projet', 'Demander à l’équipe agile d’arrêter d’itérer jusqu’à la livraison du fournisseur'],
  e: 'La coordination hybride repose sur des interfaces, des jalons et des points d’intégration clairement définis qui relient travail prédictif et adaptatif.' },
'PR255': { q: 'Les données de vélocité montrent que les équipes agiles n’atteindront pas un jalon contractuel de l’échéancier directeur. Que doit faire le chef de projet ?',
  o: ["Continuer à déclarer le jalon dans les temps en espérant que la vélocité s’améliore", "Partager la prévision et discuter périmètre ou date via la maîtrise des modifications", "Demander aux équipes de gonfler leurs estimations pour que l’écart disparaisse", "Retirer le jalon de l’échéancier directeur pour éviter de signaler un retard"],
  e: 'Les prévisions empiriques doivent être partagées tôt. Les options (périmètre, date, ressources) sont discutées, et les engagements baselinés sont modifiés via la maîtrise des modifications.' },
'PR256': { q: 'Un spécialiste sécurité rare est demandé simultanément par quatre équipes agiles. Quelle est la meilleure façon de planifier cette ressource ?',
  o: ['Laisser chaque équipe solliciter le spécialiste dès qu’elle a besoin d’aide', 'Rendre la dépendance visible et planifier conjointement la capacité du spécialiste', 'Affecter le spécialiste à une seule équipe et laisser les autres attendre', 'Recruter immédiatement quatre nouveaux spécialistes, un par équipe'],
  e: 'Les ressources partagées entre équipes doivent être visibles dans une planification commune (par exemple « big room » ou PI planning), afin d’allouer la capacité aux plus hautes priorités.' },
'PR257': { q: 'Le service d’assurance qualité attend une phase de test formelle à la fin, mais l’équipe agile teste en continu. Que doit faire le chef de projet ?',
  o: ['Demander à l’équipe agile d’arrêter de tester jusqu’au début de la phase formelle', 'Convenir de tests continus complétés par les tests d’acceptation finaux requis', 'Supprimer la phase de test formelle sans en informer l’assurance qualité', 'Laisser l’assurance qualité tout retester depuis le début, à la fin'],
  e: 'Adapter la stratégie de test combine les avantages des tests continus avec les tests d’acceptation ou réglementaires formels réellement requis.' },
'PR258': { q: 'La définition de « prêt » d’une équipe exige désormais des spécifications et conceptions complètes avant qu’une story puisse entrer dans un sprint. Quel est le risque ?',
  o: ['Aucun ; davantage de détails en amont améliore toujours la livraison agile', 'Elle devient un passage de phase qui retarde le travail', 'Elle rend les stories trop petites pour être estimées de façon fiable', 'Elle supprime le besoin d’une définition de « terminé »'],
  e: 'Une définition de « prêt » trop stricte peut devenir une porte de type cascade. Les stories doivent être suffisamment prêtes pour démarrer, les détails étant clarifiés en collaboration.' },
'PR259': { q: 'Sur un tableau Kanban, un élément est « En cours » depuis 15 jours alors que des éléments similaires prennent habituellement 4 jours. Que doit faire l’équipe ?',
  o: ["Attendre, car chaque élément est différent et a son propre rythme", "Examiner l’élément vieillissant et aider à le débloquer ou le terminer", "Le remettre dans le backlog et commencer un nouvel élément", "Augmenter la limite de WIP pour permettre plus d’éléments en cours"],
  e: 'L’âge des éléments met en évidence ceux qui sont à risque. L’équipe doit enquêter et aider à le terminer avant de commencer un nouveau travail.' },
'PR260': { q: 'Les données de temps de cycle d’une équipe montrent que 85 % des éléments se terminent en 8 jours une fois commencés. Que peut dire l’équipe à une partie prenante ?',
  o: ['Chaque nouvel élément sera terminé en exactement 8 jours', 'Un élément commencé a environ 85 % de chances d’être terminé en 8 jours', 'L’équipe peut terminer 85 % du backlog restant en 8 jours', 'Les éléments ne prendront jamais plus de 8 jours du début à la fin'],
  e: 'Les prévisions par percentile (attentes de niveau de service) expriment une probabilité, ce qui donne aux parties prenantes un engagement réaliste fondé sur les données.' },
'PR261': { q: 'Une équipe veut prévoir quand ses 50 éléments restants seront terminés, à partir de son débit hebdomadaire historique. Quelle technique donne une prévision probabiliste ?',
  o: ['Une estimation par analogie fondée sur une release passée similaire', 'Une simulation de Monte Carlo à partir des données de débit', 'La méthode du chemin critique sur les éléments restants', 'Une estimation ascendante de chaque élément en heures'],
  e: 'La simulation de Monte Carlo échantillonne de nombreuses fois le débit historique pour produire une fourchette de dates d’achèvement avec leurs probabilités.' },
'PR262': { q: 'Au milieu d’un sprint, un changement majeur du marché rend l’objectif du sprint sans valeur. Que doit-il se passer ?',
  o: ['L’équipe poursuit le sprint comme prévu jusqu’à sa fin programmée', 'Le Product Owner peut annuler le sprint et l’équipe replanifie', 'Le Scrum Master prolonge le sprint pour absorber le changement du marché', 'Les développeurs modifient l’objectif du sprint de leur propre autorité'],
  e: 'Lorsque l’objectif du sprint devient obsolète, le Product Owner peut annuler le sprint. C’est rare et ne doit être utilisé que lorsque continuer n’a plus de sens.' },
'PR263': { q: 'Plusieurs développeurs sont affectés à 50 % sur deux équipes agiles différentes. Quel est l’effet le plus probable ?',
  o: ['Une productivité accrue, car les développeurs apprécient la variété de leur travail', 'Une perte de productivité liée aux changements de contexte et une cohésion d’équipe affaiblie', 'Aucun effet, puisque le nombre total d’heures travaillées reste le même', 'Une livraison plus rapide pour les deux équipes, puisque les compétences sont partagées'],
  e: 'Les changements de contexte font perdre du temps et dispersent l’engagement. Des membres stables et dédiés sont un levier clé de la performance agile.' },
'PR264': { q: 'Qui doit faire partie d’une équipe agile ?',
  o: ['Uniquement des développeurs ; les testeurs et designers travaillent dans des équipes séparées', 'Des personnes ayant toutes les compétences nécessaires pour livrer un incrément terminé', 'Uniquement des spécialistes seniors de chaque département', 'Le sponsor du projet et les responsables fonctionnels'],
  e: 'Les équipes agiles sont pluridisciplinaires et disposent de toutes les compétences nécessaires pour créer de la valeur à chaque sprint.' },
'PR265': { q: 'Une organisation qui passe à l’agilité veut changer sa façon de financer le travail. Quelle approche est la plus conforme aux principes agiles ?',
  o: ['Financer chaque projet une seule fois, avec un périmètre et un budget fixes approuvés en amont', 'Financer des équipes pérennes ou des chaînes de valeur et ajuster l’investissement selon les résultats', 'Financer les tâches individuelles une fois terminées', 'Supprimer les budgets et laisser les équipes dépenser selon leurs besoins'],
  e: 'Les modèles de financement agiles financent souvent des équipes stables ou des chaînes de valeur et utilisent des revues régulières pour réorienter l’investissement vers le travail le plus utile.' },
'PR266': { q: 'La direction est incertaine quant à un nouveau produit et veut limiter son exposition financière. Quelle approche de financement est la plus adaptée ?',
  o: ['Approuver d’emblée le budget pluriannuel complet', 'Débloquer le financement par tranches selon les résultats validés', 'Attendre que le produit soit entièrement spécifié avant de financer quoi que ce soit', 'Financer uniquement le matériel et pas le logiciel'],
  e: 'Le financement incrémental débloque l’argent par tranches liées à des preuves, comme les résultats d’un MVP, ce qui limite l’exposition en situation d’incertitude.' },
'PR267': { q: 'Un acheteur a un contrat agile à prix fixe et veut remplacer une fonctionnalité prévue par une nouvelle de même taille. Quelle clause contractuelle le permet ?',
  o: ['Une clause interdisant toute modification du périmètre après signature', 'Une clause permettant d’échanger du périmètre contre des éléments de taille égale', 'Une clause exigeant un nouveau contrat pour chaque modification demandée', 'Une clause de pénalités de retard couvrant la livraison tardive de fonctionnalités'],
  e: 'Les contrats agiles comportent souvent des clauses « change for free » : le client peut échanger des éléments non commencés contre de nouveaux éléments de taille équivalente sans changer le prix.' },
'PR268': { q: 'La vélocité d’une équipe varie fortement d’un sprint à l’autre (entre 18 et 42 points), ce qui rend les prévisions peu fiables. Qu’est-ce qui aiderait le plus ?',
  o: ['Fixer un objectif de vélocité que l’équipe doit atteindre à chaque sprint', 'Découper les stories plus finement et garder une équipe stable', 'Estimer en heures plutôt qu’en story points pour plus de précision', 'Allonger les sprints à deux mois pour lisser la variation'],
  e: 'Des stories plus petites et des équipes stables réduisent la variabilité. Les grosses stories créent un achèvement irrégulier et une vélocité imprévisible.' },
'PR269': { q: 'Une release agile faisant partie d’un programme prédictif plus large a été livrée. Que doit garantir le chef de projet pour la clôturer correctement ?',
  o: ["Simplement célébrer la release avec l’équipe et passer à la suite", "Obtenir l’acceptation, capter les leçons et finaliser la transition", "Archiver le backlog et libérer immédiatement toute l’équipe", "Attendre la fin de tout le programme avant de clôturer la release"],
  e: 'Même au sein d’un programme, une release nécessite une acceptation formelle, une transition vers l’exploitation, la mise à jour de la documentation et des leçons apprises.' },
'PR270': { q: 'Le carnet de produit contient 600 éléments, dont beaucoup datent de plusieurs années et n’ont jamais été priorisés. Que doit faire le Product Owner ?',
  o: ['Tout conserver, car chaque ancienne idée pourrait devenir utile plus tard', 'Supprimer ou archiver les éléments qui n’ont plus de valeur', 'Demander à l’équipe d’estimer en détail les 600 éléments avant de les ordonner', 'Répartir le backlog entre les développeurs pour le rendre gérable'],
  e: 'Un backlog sain est émergent et ordonné. Élaguer les éléments périmés le garde ciblé et réduit le gaspillage lors de l’affinage.' },
'PR271': { q: 'Quel est le principal avantage financier d’une livraison incrémentale de la valeur ?',
  o: ['Le coût total du projet est toujours inférieur à celui d’une release unique', 'La valeur est obtenue plus tôt, ce qui améliore le rendement et réduit le risque', 'Aucun test n’est nécessaire avant l’assemblage de la release finale', 'Le périmètre complet peut être fixé et approuvé dès le départ'],
  e: 'Des releases incrémentales précoces démarrent plus tôt le flux de bénéfices, apportent des retours et réduisent le risque de construire le mauvais produit.' },
'PR272': { q: 'Qu’est-ce qu’une durée limitée (timebox) ?',
  o: ['Un conteneur pour les documents produits pendant un sprint', 'Une période de temps fixe et maximale pour une activité', 'Une estimation du temps que prendra une story', 'Le temps écoulé entre deux releases'],
  e: 'Une timebox est une durée maximale fixe. Elle oblige à prioriser et à se concentrer ; c’est le périmètre qui s’ajuste à la timebox.' },
'PR273': { q: 'L’équipe agile d’un fournisseur travaille sous contrat pour l’organisation. Quelle est la meilleure mesure de la performance du fournisseur ?',
  o: ["Le nombre d’heures facturées chaque mois par rapport au contrat", "Des incréments conformes à la définition de « terminé » à chaque sprint", "Le nombre de documents et rapports livrés à l’acheteur chaque mois", "La vélocité de l’équipe du fournisseur comparée à celle des équipes internes"],
  e: 'La performance d’un fournisseur agile se juge au mieux par la valeur fonctionnelle livrée qui respecte les normes de qualité convenues.' },
'PR274': { q: 'Qui décide si une user story terminée est acceptée à la fin du sprint ?',
  o: ['Le Scrum Master', 'Le Product Owner', 'Le testeur qui l’a vérifiée', 'Le sponsor du projet'],
  e: 'Le Product Owner accepte ou rejette le travail selon les critères d’acceptation et la définition de « terminé ».' },
'PR275': { q: 'Une équipe a consacré une courte « itération zéro » avant son premier sprint. Quel est l’objectif approprié d’une telle itération ?',
  o: ['Rédiger toutes les exigences en détail avant le début du développement', 'Mettre en place le minimum nécessaire pour commencer à livrer', 'Livrer d’abord la fonctionnalité la plus utile aux clients', 'Réaliser en amont toute la conception de l’architecture'],
  e: 'Si elle est utilisée, une itération initiale doit être courte et centrée sur la mise en place minimale nécessaire pour livrer de la valeur, pas sur une grande conception initiale.' },
'PR276': { q: 'Une story a été estimée à 5 points, mais lors de l’affinage l’équipe découvre qu’elle est beaucoup plus complexe. Que doit-il se passer ?',
  o: ['Conserver l’estimation initiale pour protéger le plan de release', 'Réestimer la story selon la nouvelle compréhension', 'Demander au Product Owner de choisir une nouvelle estimation', 'Répartir les points équitablement entre les autres stories'],
  e: 'Les estimations sont mises à jour lorsque la compréhension s’améliore, tant que le travail n’est pas terminé. Les prévisions sont ensuite actualisées.' },
'PR277': { q: 'Quelle pratique de l’Extreme Programming (XP) vise à livrer fréquemment de petites mises à jour aux utilisateurs ?',
  o: ['Les petites releases', 'Le jeu de planification', 'La métaphore du système', 'Les normes de codage'],
  e: 'Les petites releases livrent rapidement de la valeur et apportent des retours fréquents. Les autres pratiques XP comprennent le jeu de planification, le TDD, la programmation en binôme et l’intégration continue.' },
'PR278': { q: 'On demande à une équipe agile d’indiquer le pourcentage d’achèvement d’une fonctionnalité en cours. Quelle est l’approche la plus fiable ?',
  o: ["Estimer le pourcentage à partir des heures passées jusqu’ici sur la fonctionnalité", "Ne compter que les stories terminées ; le partiel compte comme non terminé", "Indiquer 50 % pour toute story commencée", "Demander à chaque développeur son estimation personnelle de l’avancement"],
  e: 'L’avancement agile se mesure en travail terminé. Déclarer du travail partiel crée le syndrome du « terminé à 90 % » et cache les risques.' },
'PR279': { q: 'Un projet hybride suit les coûts de composantes prédictives et agiles. Quelle approche donne au sponsor une vue financière cohérente ?',
  o: ['Ne rendre compte que des coûts prédictifs, puisque les coûts agiles varient d’un sprint à l’autre', 'Combiner l’EVM pour le travail prédictif et des prévisions de consommation pour le travail agile', 'Convertir tout le travail agile en lots de travail à prix fixe pour le reporting', 'Ne rendre compte des coûts agiles qu’à la fin du projet, lorsqu’ils sont définitifs'],
  e: 'Le reporting financier hybride intègre les mesures adaptées à chaque approche dans une vue unique pour les décideurs.' },
'PR280': { q: 'L’équipe utilise un diagramme de flux cumulé. Quel motif indique un flux sain et stable ?',
  o: ['Des bandes qui s’élargissent régulièrement dans le temps', 'Des bandes parallèles de largeur à peu près constante', 'Une bande « Terminé » qui reste plate pendant des semaines', 'Des bandes qui se croisent'],
  e: 'Des bandes parallèles de largeur stable indiquent un WIP stable et un débit régulier. Des bandes qui s’élargissent signalent des goulots ; une bande « Terminé » plate montre que rien n’est terminé.' },
'PR281': { q: 'Les développeurs commencent sans cesse de nouvelles stories avant de terminer celles en cours. Plusieurs stories sont à 80 % à la fin de chaque sprint. Que doit encourager le Scrum Master ?',
  o: ['Commencer plus de stories pour que tout le monde reste occupé', 'Limiter le WIP et terminer avant de commencer un nouveau travail', 'Compter les stories partiellement terminées dans la vélocité', 'Allonger les sprints pour que les stories puissent être terminées'],
  e: '« Arrêtez de commencer, commencez à finir. » Limiter le WIP améliore le flux et permet de terminer les stories dans le sprint.' },
'PR282': { q: 'Un Product Owner demande comment montrer aux parties prenantes la valeur livrée jusqu’ici dans une release. Quelle est la meilleure approche ?',
  o: ["Montrer le nombre d’heures travaillées par l’équipe à chaque sprint", "Faire la démonstration du produit et présenter les résultats d’usage", "Montrer le nombre de tâches terminées par chaque développeur", "Montrer seulement le graphique de vélocité de l’équipe"],
  e: 'La valeur se montre par le produit fonctionnel et les résultats, pas par des mesures d’activité.' },
'PR283': { q: '<p>Utilisez les informations du réseau ci-dessous.</p><table><tr><th>Activité</th><th>Durée (jours)</th><th>Prédécesseur</th></tr><tr><td>A</td><td>4</td><td>—</td></tr><tr><td>B</td><td>6</td><td>A</td></tr><tr><td>C</td><td>3</td><td>A</td></tr><tr><td>D</td><td>5</td><td>C</td></tr><tr><td>E</td><td>2</td><td>B, D</td></tr></table><p>Quelle est la durée du projet, en jours ?</p>',
  e: 'Chemins : A-B-E = 4+6+2 = 12 ; A-C-D-E = 4+3+5+2 = 14. Le chemin critique est A-C-D-E, donc la durée est de 14 jours.' },
'PR284': { q: '<p>Utilisez les informations du réseau ci-dessous.</p><table><tr><th>Activité</th><th>Durée (jours)</th><th>Prédécesseur</th></tr><tr><td>A</td><td>4</td><td>—</td></tr><tr><td>B</td><td>6</td><td>A</td></tr><tr><td>C</td><td>3</td><td>A</td></tr><tr><td>D</td><td>5</td><td>C</td></tr><tr><td>E</td><td>2</td><td>B, D</td></tr></table><p>Quelle est la marge totale de l’activité B, en jours ?</p>',
  e: 'Chemin critique A-C-D-E = 14 jours ; chemin A-B-E = 12 jours. B peut glisser de 14 − 12 = 2 jours sans retarder le projet.' },
'PR285': { q: 'Un contrat à prix fixe avec intéressement (FPIF) prévoit un coût cible de 200 000 $, des honoraires cibles de 20 000 $, un partage acheteur/vendeur de 80/20 et un prix plafond de 250 000 $. Le coût réel est de 180 000 $. Quel est le prix final payé par l’acheteur, en dollars ?',
  e: 'Économie = 200 000 − 180 000 = 20 000. Part du vendeur = 20 % × 20 000 = 4 000, donc honoraires = 20 000 + 4 000 = 24 000. Prix = 180 000 + 24 000 = 204 000 $ (sous le plafond).' },
'PR286': { q: 'Un contrat en coûts remboursables avec intéressement (CPIF) prévoit un coût estimé de 100 000 $, des honoraires cibles de 10 000 $ et un partage acheteur/vendeur de 70/30. Le coût réel est de 120 000 $. Quel est le montant total payé par l’acheteur, en dollars ?',
  e: 'Dépassement = 20 000. Part du vendeur = 30 % × 20 000 = 6 000, donc honoraires = 10 000 − 6 000 = 4 000. Total = 120 000 + 4 000 = 124 000 $.' },
'PR287': { q: 'La valeur acquise (EV) est de 120 000 $ et la valeur planifiée (PV) de 150 000 $. Quel est l’écart de délais (SV), en dollars ? (Saisissez un nombre négatif si nécessaire.)',
  e: 'SV = EV − PV = 120 000 − 150 000 = −30 000 $. Le projet est en retard.' },
'PR288': { q: 'Le BAC est de 100 000 $, l’EV de 40 000 $ et l’AC de 50 000 $. Quel indice de performance pour l’achèvement (TCPI) faut-il pour terminer dans le BAC ? (Saisissez un nombre décimal, par exemple 1,05.)',
  e: 'TCPI = (BAC − EV) / (BAC − AC) = 60 000 / 50 000 = 1,2. Le travail restant doit être réalisé 20 % plus efficacement.' },
'PR289': { q: 'Le budget à l’achèvement (BAC) est de 300 000 $ et l’estimation à l’achèvement (EAC) de 360 000 $. Quel est l’écart à l’achèvement (VAC), en dollars ? (Saisissez un nombre négatif si nécessaire.)',
  e: 'VAC = BAC − EAC = 300 000 − 360 000 = −60 000 $. Le projet devrait finir au-dessus du budget.' },
'PR290': { q: 'Les hypothèses d’estimation initiales ne sont plus valables. Le coût réel à date est de 70 000 $ et la nouvelle estimation ascendante de l’équipe pour le travail restant est de 50 000 $. Quelle est l’EAC, en dollars ?',
  e: 'Lorsque le plan initial n’est plus valable, EAC = AC + ETC ascendante = 70 000 + 50 000 = 120 000 $.' },
'PR291': { q: '<p>Une carte de contrôle d’un processus de production a une moyenne de 50 mm, une limite de contrôle supérieure de 53 mm et inférieure de 47 mm. Les dernières mesures sont :</p><table><tr><th>Échantillon</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr><tr><td>mm</td><td>49,5</td><td>51,0</td><td>50,2</td><td>54,1</td><td>49,8</td></tr></table><p>Que doit conclure le chef de projet ?</p>',
  o: ['Le processus est maîtrisé car la moyenne des échantillons est proche de 50 mm', 'Le processus est hors contrôle ; rechercher la cause spéciale de l’échantillon 4', 'Les limites de contrôle doivent être élargies pour inclure l’échantillon 4', 'L’échantillon 4 peut être ignoré comme une probable erreur de mesure'],
  e: 'Tout point hors des limites de contrôle indique un processus hors contrôle. La cause spéciale doit être identifiée avant de considérer le processus comme stable.' },
'PR292': { q: 'Tester chaque unité d’un produit la détruirait. Quelle technique l’équipe qualité doit-elle utiliser ?',
  o: ["L’inspection à 100 % des unités", "L’échantillonnage statistique", "Le benchmarking des fournisseurs", "L’analyse de Pareto des défauts"],
  e: 'L’échantillonnage statistique inspecte un sous-ensemble représentatif lorsque tout tester est trop coûteux, trop long ou destructif.' },
'PR293': { q: 'L’équipe veut identifier quelle combinaison de facteurs (température, pression, matériau) donne la meilleure qualité de produit avec le moins de tests. Quelle technique est la plus adaptée ?',
  o: ['Les plans d’expériences', 'Le diagramme de causes et effets', 'La feuille de relevé', 'Le logigramme'],
  e: 'Les plans d’expériences font varier systématiquement plusieurs facteurs à la fois pour trouver efficacement leurs effets et les réglages optimaux.' },
'PR294': { q: 'Quel est l’objectif principal d’un audit qualité ?',
  o: ['Inspecter les livrables pour détecter les défauts avant l’acceptation du client', 'Vérifier la conformité aux politiques et processus, et trouver des améliorations', 'Calculer le coût total de la qualité du projet pour le sponsor', 'Approuver ou rejeter les demandes de modification liées aux normes de qualité'],
  e: 'Les audits qualité sont des revues structurées et indépendantes vérifiant si les activités du projet respectent les politiques et procédures ; ils identifient les bonnes pratiques et les lacunes.' },
'PR295': { q: 'Quelle est la différence entre le contenu du produit et le contenu du projet ?',
  o: ['C’est la même chose, décrite du point de vue du client et de celui de l’équipe', 'Le contenu du produit, ce sont les caractéristiques du résultat ; le contenu du projet, le travail pour le livrer', 'Le contenu du projet, ce sont les caractéristiques du résultat ; le contenu du produit, le travail pour le livrer', 'Le contenu du produit ne concerne que les projets agiles ; celui du projet, que les prédictifs'],
  e: 'Le contenu du produit décrit les caractéristiques et fonctions du produit ; le contenu du projet est le travail réalisé pour le livrer. Le premier se mesure par rapport aux exigences, le second par rapport au plan.' },
'PR296': { q: 'Quel document indique explicitement ce qui est exclu du projet, afin d’aider à gérer les attentes des parties prenantes ?',
  o: ['La charte du projet', 'L’énoncé du contenu du projet', 'La documentation des exigences', 'Le registre des parties prenantes'],
  e: 'L’énoncé du contenu du projet comprend les exclusions, qui précisent ce qui est hors périmètre.' },
'PR297': { q: 'L’ancien système ne peut pas être arrêté tant que le nouveau système n’a pas commencé à fonctionner. De quel type de dépendance s’agit-il ?',
  o: ['Fin-début', 'Début-début', 'Fin-fin', 'Début-fin'],
  e: 'Début-fin : le successeur (arrêt de l’ancien système) ne peut se terminer tant que le prédécesseur (démarrage du nouveau système) n’a pas commencé. C’est la relation la plus rare.' },
'PR298': { q: 'Une analyse de l’échéancier montre une marge totale négative sur le chemin critique. Qu’est-ce que cela signifie ?',
  o: ['Le projet finira plus tôt que la date imposée', 'Le plan ne peut pas tenir la date imposée sans action corrective', 'Les activités du chemin critique peuvent être retardées sans impact', 'L’échéancier ne contient aucune dépendance entre activités'],
  e: 'Une marge négative signifie que le plan actuel se termine après une date imposée. Une compression ou d’autres actions correctives sont nécessaires.' },
'PR299': { q: 'Quelle affirmation sur le chemin critique est correcte ?',
  o: ['C’est le chemin qui comporte le plus d’activités', 'Il peut changer pendant le projet à mesure que le travail avance', 'Il contient toujours les activités les plus coûteuses', 'Il est figé une fois la référence de base de l’échéancier approuvée'],
  e: 'Le chemin critique est le chemin le plus long du réseau. Les retards, changements et l’avancement peuvent créer un nouveau chemin critique ; il faut donc le surveiller.' },
'PR300': { q: 'Un projet a déjà dépensé 400 000 $. Le sponsor doit décider s’il continue. Comment traiter l’argent déjà dépensé dans cette décision ?',
  o: ['Comme le facteur le plus important, car arrêter le gaspillerait', 'Comme un coût irrécupérable qui ne doit pas influencer la décision', 'Comme une raison d’augmenter le budget', 'Comme une partie de l’estimation restante'],
  e: 'Les coûts irrécupérables ne peuvent pas être récupérés et ne doivent pas guider les décisions futures. Les décisions doivent reposer sur les coûts et bénéfices futurs.' },
'PR301': { q: 'Deux options d’équipement ont des prix d’achat différents et des coûts d’exploitation et de maintenance différents sur 10 ans. Quelle approche utiliser pour les comparer ?',
  o: ['Comparer uniquement les prix d’achat', 'Le coût global du cycle de vie', 'L’estimation par analogie', 'L’analyse de la valeur acquise'],
  e: 'Le coût du cycle de vie prend en compte le coût total de possession, y compris l’acquisition, l’exploitation, la maintenance et l’élimination.' },
'PR302': { q: 'Quel document d’approvisionnement décrit l’élément à acquérir de façon suffisamment détaillée pour que les vendeurs potentiels sachent s’ils peuvent le fournir ?',
  o: ['L’énoncé des travaux d’approvisionnement', 'Les critères de sélection des sources', 'Le registre des documents d’appel d’offres', 'La décision de faire ou acheter'],
  e: 'L’énoncé des travaux d’approvisionnement décrit le produit, le service ou le résultat acquis de façon suffisamment détaillée pour que les vendeurs évaluent leur capacité.' },
'PR303': { q: 'Le chef de projet de l’acheteur n’est pas satisfait d’un sous-traitant engagé par le vendeur. Que doit-il faire ?',
  o: ['Donner directement des instructions au sous-traitant pour régler le problème', 'Soulever le problème auprès du vendeur, qui en est responsable', 'Résilier le contrat du sous-traitant au nom du vendeur', 'Retenir le paiement du sous-traitant jusqu’à ce que sa performance s’améliore'],
  e: 'Effet relatif des contrats : l’acheteur a un contrat avec le vendeur, pas avec le sous-traitant. Les problèmes sont soulevés auprès du vendeur.' },
'PR304': { q: 'Un vendeur ne peut pas livrer parce qu’un séisme majeur a détruit son usine. Quelle clause contractuelle est la plus pertinente ?',
  o: ['Les pénalités forfaitaires', 'La force majeure', 'La retenue de garantie', 'La garantie'],
  e: 'Les clauses de force majeure couvrent les événements extraordinaires échappant au contrôle des parties ; elles excusent ou retardent généralement l’exécution.' },
'PR305': { q: 'Avant d’évaluer les propositions des vendeurs, l’acheteur prépare sa propre estimation du coût du travail. Quel est l’objectif principal de cette estimation indépendante ?',
  o: ["Fixer le prix que le vendeur retenu devra obligatoirement accepter", "Servir de référence et détecter des prix irréalistes", "Remplacer les critères de sélection des sources pour l’évaluation", "Calculer la marge bénéficiaire visée par chaque vendeur"],
  e: 'Les estimations indépendantes servent de référence. De grands écarts peuvent indiquer que l’énoncé des travaux est flou ou qu’un vendeur l’a mal compris.' },
'PR306': { q: 'Quel document décrit comment les ressources physiques et humaines seront acquises, gérées et libérées ?',
  o: ['Le plan de management des ressources', 'Le plan de management des approvisionnements', 'Le registre des ressources humaines', 'Le calendrier des ressources'],
  e: 'Le plan de management des ressources couvre l’identification, l’acquisition, la gestion, le développement et la libération des ressources humaines et physiques.' },
'PR307': { q: 'Une demande de modification approuvée doit maintenant être réalisée par l’équipe. Dans quel processus la modification est-elle mise en œuvre ?',
  o: ['Mettre en œuvre la maîtrise intégrée des modifications', 'Diriger et gérer le travail du projet', 'Surveiller et maîtriser le travail du projet', 'Clore le projet ou la phase'],
  e: 'La maîtrise intégrée des modifications approuve ou rejette les modifications ; les modifications approuvées sont mises en œuvre dans Diriger et gérer le travail du projet.' },
'PR308': { q: 'Que doit contenir le rapport final du projet ?',
  o: ["Uniquement le coût final du projet comparé au budget initial", "Une synthèse de la performance au regard des objectifs et références", "Les journaux d’activité quotidiens détaillés de chaque membre de l’équipe", "Uniquement la liste des problèmes encore ouverts à la clôture"],
  e: 'Le rapport final résume la performance du projet par rapport à ses objectifs et références de base, le produit final et la façon dont les bénéfices métier seront obtenus.' }
});
